type timeoutErr string

func (t timeoutErr) Error() string { return string(t) }

func errTimeout(stage string) error {
	return timeoutErr(stage + " timeout")
}

func sendTriggerGTPUPacket(dst string, teid uint32, ueIP, innerDst string, innerDstPort uint16) error {
	raddr, err := net.ResolveUDPAddr("udp", dst)
	if err != nil {
		return fmt.Errorf("resolve N3 addr %s: %w", dst, err)
	}

	conn, err := net.DialUDP("udp", nil, raddr)
	if err != nil {
		return fmt.Errorf("dial N3 %s: %w", dst, err)
	}
	defer conn.Close()

	srcIP := net.ParseIP(ueIP)
	if srcIP == nil {
		return fmt.Errorf("invalid UE IPv4: %s", ueIP)
	}
	dstIP := net.ParseIP(innerDst)
	if dstIP == nil {
		return fmt.Errorf("invalid inner destination IPv4: %s", innerDst)
	}

	srcPort := uint16(20000 + rand.Intn(20000))
	payload := []byte("pfcp-fake-smf trigger")

	inner := buildInnerIPv4UDP(srcIP, dstIP, srcPort, innerDstPort, payload)
	gtp := buildGTPU(teid, inner)

	if _, err := conn.Write(gtp); err != nil {
		return fmt.Errorf("send gtp-u to %s: %w", dst, err)
	}

	log.Printf("sent trigger GTP-U packet to %s (TEID=0x%x, inner %s:%d -> %s:%d, payload=%d bytes)", dst, teid, srcIP, srcPort, dstIP, innerDstPort, len(payload))
	return nil
}

// helpers for PFCP-in-GTP-U
func splitHostPortDefault(addr string, defPort int) (string, int) {
	host, portStr, err := net.SplitHostPort(addr)
	if err != nil {
		// if missing port, assume defPort
		return addr, defPort
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		return host, defPort
	}
	return host, port
}

func csum(data []byte) uint16 {
	sum := uint32(0)
	for len(data) > 1 {
		sum += uint32(binary.BigEndian.Uint16(data))
		data = data[2:]
	}
	if len(data) > 0 {
		sum += uint32(data[0]) << 8
	}
	for (sum >> 16) > 0 {
		sum = (sum & 0xFFFF) + (sum >> 16)
	}
	return ^uint16(sum)
}

func buildInnerIPv4UDP(srcIP, dstIP net.IP, srcPort, dstPort uint16, payload []byte) []byte {
	src := srcIP.To4()
	dst := dstIP.To4()
	if src == nil || dst == nil {
		log.Fatalf("only IPv4 supported for inner packet")
	}
	udpLen := 8 + len(payload)
	ipLen := 20 + udpLen

	ip := make([]byte, 20)
	ip[0] = 0x45
	binary.BigEndian.PutUint16(ip[2:], uint16(ipLen))
	binary.BigEndian.PutUint16(ip[4:], uint16(rand.Intn(0xffff)))
	ip[6] = 0x40
	ip[8] = 64
	ip[9] = 17
	copy(ip[12:], src)
	copy(ip[16:], dst)
	binary.BigEndian.PutUint16(ip[10:], csum(ip))

	udp := make([]byte, 8)
	binary.BigEndian.PutUint16(udp[0:], srcPort)
	binary.BigEndian.PutUint16(udp[2:], dstPort)
	binary.BigEndian.PutUint16(udp[4:], uint16(udpLen))
	psh := make([]byte, 12)
	copy(psh[0:], src)
	copy(psh[4:], dst)
	psh[9] = 17
	binary.BigEndian.PutUint16(psh[10:], uint16(udpLen))
	udpChkData := append(append(psh, udp...), payload...)
	binary.BigEndian.PutUint16(udp[6:], csum(udpChkData))

	pkt := make([]byte, 0, ipLen)
	pkt = append(pkt, ip...)
	pkt = append(pkt, udp...)
	pkt = append(pkt, payload...)
	return pkt
}

func buildGTPU(teid uint32, inner []byte) []byte {
	gtp := make([]byte, 8+len(inner))
	gtp[0] = 0x30
	gtp[1] = 0xFF // T-PDU
	binary.BigEndian.PutUint16(gtp[2:], uint16(len(inner)))
	binary.BigEndian.PutUint32(gtp[4:], teid)
	copy(gtp[8:], inner)
	return gtp
}
